import type { TheoryTopic } from "../theory";

const m = String.raw;
type Section = TheoryTopic["sections"][number];
type Example = TheoryTopic["examples"][number];
const section = (title: string, body: string[], formulas: string[] = []): Section => ({ title, body, formulas });
const example = (title: string, answer: string, steps: (string | { text: string; latex: string })[]): Example => ({
  title, answer, steps: steps.map((step) => typeof step === "string" ? { text: step } : step),
});
function article(
  exam: "ОГЭ" | "ЕГЭ", number: number, title: string, description: string,
  prerequisites: string[], sections: Section[], examples: Example[], difficulties: string[],
): TheoryTopic {
  const id = `${exam === "ОГЭ" ? "oge" : "ege-profile"}-number-${number}`;
  const part = number <= (exam === "ОГЭ" ? 19 : 12) ? 1 : 2;
  return {
    id, materialId: `${id}-guide`, subjectId: "math", examType: [exam], examNumbers: [number],
    part, coverage: "exam-topic", title: `№${number}. ${title}`, description, prerequisites,
    source: { kind: "author", label: "Авторский учебный материал · структура проекта 2026" },
    readMinutes: part === 1 ? 6 : 10, sections, examples, difficulties,
  };
}

